//! The beam entities, one module per table: each table's Diesel
//! schema, row, JSON and riverbase entity, which the query resources read and
//! the beam stores write. Generated by `scripts/gen_query_resources.py`: edit
//! `crates/beam_domain/query/spec.json` and regenerate. `root`, `value` and
//! `write` are written by hand.

use std::sync::Arc;

use diesel_async::AsyncPgConnection;
use riverbase_core::datastore::{DataResult, ErasedEntity, PgDataStore, PgPool};
use serde_json::Value;
use uuid::Uuid;

mod root;
pub mod value;
pub mod write;

pub use root::{RootById, ROOT_RESOURCES};

pub mod agent;
pub mod agent_action;
pub mod agent_context_manifest;
pub mod agent_cost_event;
pub mod agent_dead_letter;
pub mod agent_evaluation_result;
pub mod agent_evaluation_run;
pub mod agent_event;
pub mod agent_execution;
pub mod agent_execution_event;
pub mod agent_feedback;
pub mod agent_interaction;
pub mod agent_knowledge_chunk;
pub mod agent_knowledge_document;
pub mod agent_memory;
pub mod agent_message;
pub mod agent_outbox_event;
pub mod agent_profile;
pub mod agent_revision;
pub mod agent_run;
pub mod agent_security_decision;
pub mod agent_session;
pub mod agent_step;
pub mod agent_suggestion;
pub mod agent_task;
pub mod agent_usage_event;
pub mod agent_usage_plan;
pub mod agent_usage_profile;
pub mod model;
pub mod tool;

/// The `upsert_from_json` of a table the spec does not make writable: beam
/// writes it with its own SQL.
///
/// # Errors
/// Always `BEM-145`.
#[allow(clippy::unused_async)] // `pg_domain_entity!` awaits it.
pub async fn read_only(_conn: &mut AsyncPgConnection, _id: Uuid, _data: &Value) -> DataResult<()> {
    Err(crate::BEM_145.raise())
}

/// The beam datastore (plan 013 D3): every table's entity, for riverbase's
/// command and query engines and the beam stores' writes. The root resources
/// answer riverbase's root lookup with the identifier ([`RootById`]).
#[must_use]
pub fn datastore(pool: PgPool) -> PgDataStore {
    let entities: [Arc<dyn ErasedEntity>; 30] = [
        Arc::new(agent::AgentEntity),
        Arc::new(agent_revision::AgentRevisionEntity),
        Arc::new(model::ModelEntity),
        Arc::new(tool::ToolEntity),
        Arc::new(agent_session::AgentSessionEntity),
        Arc::new(agent_execution::AgentExecutionEntity),
        Arc::new(agent_interaction::AgentInteractionEntity),
        Arc::new(agent_run::AgentRunEntity),
        Arc::new(agent_step::AgentStepEntity),
        Arc::new(agent_message::AgentMessageEntity),
        Arc::new(agent_action::AgentActionEntity),
        Arc::new(agent_profile::AgentProfileEntity),
        Arc::new(agent_suggestion::AgentSuggestionEntity),
        Arc::new(agent_usage_plan::AgentUsagePlanEntity),
        Arc::new(agent_usage_profile::AgentUsageProfileEntity),
        Arc::new(agent_knowledge_document::AgentKnowledgeDocumentEntity),
        Arc::new(agent_knowledge_chunk::AgentKnowledgeChunkEntity),
        Arc::new(agent_memory::AgentMemoryEntity),
        Arc::new(agent_event::AgentEventEntity),
        Arc::new(agent_evaluation_run::AgentEvaluationRunEntity),
        Arc::new(agent_evaluation_result::AgentEvaluationResultEntity),
        Arc::new(agent_feedback::AgentFeedbackEntity),
        Arc::new(agent_task::AgentTaskEntity),
        Arc::new(agent_dead_letter::AgentDeadLetterEntity),
        Arc::new(agent_context_manifest::AgentContextManifestEntity),
        Arc::new(agent_security_decision::AgentSecurityDecisionEntity),
        Arc::new(agent_execution_event::AgentExecutionEventEntity),
        Arc::new(agent_outbox_event::AgentOutboxEventEntity),
        Arc::new(agent_usage_event::AgentUsageEventEntity),
        Arc::new(agent_cost_event::AgentCostEventEntity),
    ];
    entities
        .into_iter()
        .fold(PgDataStore::new(pool), |store, entity| {
            store.register_entity(root::wrap(entity))
        })
}
